 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8" />
   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
       --panel: rgba(15, 23, 42, 0.88);
       --panel-border: rgba(148, 163, 184, 0.18);
       --text: #e5eefc;
       --muted: #9fb0cc;
       --accent: #7c3aed;
       --accent-strong: #8b5cf6;
       --danger: #fb7185;
       --field-bg: rgba(2, 6, 23, 0.72);
       --field-border: rgba(148, 163, 184, 0.24);
       --shadow: 0 24px 70px rgba(0, 0, 0, 0.45);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, rgba(124, 58, 237, 0.22), transparent 35%),
         linear-gradient(180deg, #050816 0%, #0b1020 100%);
       color: var(--text);
       display: grid;
       place-items: center;
       padding: 24px;
     }

     .support-card {
       width: min(100%, 760px);
       background: var(--panel);
       border: 1px solid var(--panel-border);
       border-radius: 24px;
       box-shadow: var(--shadow);
       overflow: hidden;
       backdrop-filter: blur(16px);
     }

     .support-header {
       padding: 32px 32px 8px;
     }

     .eyebrow {
       margin: 0 0 8px;
       color: #c4b5fd;
       font-size: 0.85rem;
       letter-spacing: 0.12em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0;
       font-size: clamp(1.7rem, 2.4vw, 2.4rem);
       line-height: 1.15;
     }

     .subtitle {
       margin: 12px 0 0;
       max-width: 60ch;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       padding: 24px 32px 32px;
     }

     .form-grid {
       display: grid;
       gap: 18px;
     }

     .form-field {
       display: grid;
       gap: 8px;
     }

     label {
       font-weight: 600;
       color: #dbe7ff;
     }

     input {
       width: 100%;
       border: 1px solid var(--field-border);
       border-radius: 14px;
       padding: 14px 16px;
       background: var(--field-bg);
       color: var(--text);
       font: inherit;
       transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
     }

     input::placeholder {
       color: #71809f;
     }

     input:focus {
       outline: none;
       border-color: rgba(139, 92, 246, 0.75);
       box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.18);
     }

     .helper-text {
       color: var(--muted);
       font-size: 0.92rem;
       line-height: 1.4;
     }

     .error-text {
       display: none;
       color: var(--danger);
       font-size: 0.92rem;
       line-height: 1.4;
     }

     .form-field.is-invalid input {
       border-color: rgba(251, 113, 133, 0.9);
       box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.12);
     }

     .form-field.is-invalid .error-text {
       display: block;
     }

     .actions {
       margin-top: 22px;
       display: flex;
       justify-content: flex-end;
     }

     button {
       border: 0;
       border-radius: 14px;
       padding: 14px 22px;
       background: linear-gradient(135deg, var(--accent), var(--accent-strong));
       color: white;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       box-shadow: 0 14px 32px rgba(124, 58, 237, 0.3);
       transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
     }

     button:hover {
       transform: translateY(-1px);
       filter: brightness(1.04);
       box-shadow: 0 16px 36px rgba(124, 58, 237, 0.34);
     }

     button:active {
       transform: translateY(0);
     }

     @media (max-width: 640px) {
       .support-header,
       form {
         padding-left: 20px;
         padding-right: 20px;
       }

       .actions {
         justify-content: stretch;
       }

       button {
         width: 100%;
       }
     }
   </style>
 </head>
 <body>
   <main class="support-card">
     <header class="support-header">
       <p class="eyebrow">Support</p>
       <h1>Contact our team</h1>
       <p class="subtitle">Send us your details and we&apos;ll get back to you as soon as possible.</p>
     </header>

     <form id="support-form" novalidate>
       <div class="form-grid">
         <div class="form-field" data-field="fullName">
           <label for="fullName">Full name</label>
           <input id="fullName" name="fullName" type="text" autocomplete="name" required placeholder="Jane Doe" />
           <div class="error-text">Please enter your full name.</div>
         </div>

         <div class="form-field" data-field="email">
           <label for="email">Email address</label>
           <input id="email" name="email" type="email" autocomplete="email" required placeholder="jane@example.com" />
           <div class="error-text">Please enter a valid email address.</div>
         </div>

         <div class="form-field" data-field="phone">
           <label for="phone">Phone number</label>
           <input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="+1 (555) 123-4567" />
           <div class="helper-text">Optional. Use a format like +1 (555) 123-4567 or 555-123-4567.</div>
           <div class="error-text">Please enter a valid phone number format.</div>
         </div>
       </div>

       <div class="actions">
         <button type="submit">Submit</button>
       </div>
     </form>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const fields = [
       {
         key: 'fullName',
         input: document.getElementById('fullName'),
         wrapper: document.querySelector('[data-field="fullName"]'),
         validate(value) {
           return value.trim().length > 0;
         }
       },
       {
         key: 'email',
         input: document.getElementById('email'),
         wrapper: document.querySelector('[data-field="email"]'),
         validate(value) {
           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
         }
       },
       {
         key: 'phone',
         input: document.getElementById('phone'),
         wrapper: document.querySelector('[data-field="phone"]'),
         validate(value) {
           if (!value.trim()) {
             return true;
           }
           return /^[+()\d\s.-]{7,}$/.test(value.trim());
         }
       }
     ];

     function setValidity(field, isValid) {
       field.wrapper.classList.toggle('is-invalid', !isValid);
       field.input.setAttribute('aria-invalid', String(!isValid));
     }

     function validateField(field) {
       const isValid = field.validate(field.input.value);
       setValidity(field, isValid);
       return isValid;
     }

     fields.forEach((field) => {
       field.input.addEventListener('input', () => {
         if (field.wrapper.classList.contains('is-invalid')) {
           validateField(field);
         }
       });

       field.input.addEventListener('blur', () => {
         validateField(field);
       });
     });

     form.addEventListener('submit', (event) => {
       const isFormValid = fields.map(validateField).every(Boolean);

       if (!isFormValid) {
         event.preventDefault();
         const firstInvalid = fields.find((field) => field.wrapper.classList.contains('is-invalid'));
         if (firstInvalid) {
           firstInvalid.input.focus();
         }
         return;
       }

       event.preventDefault();
       form.reset();
       fields.forEach((field) => setValidity(field, true));
     });

     fields.forEach((field) => setValidity(field, true));
   </script>
 </body>
 </html>

